using System.Text.Json;
namespace AgentRadar.Core;

/// One shared FIFO owns route, readback, send and original-session confirmation.
public sealed class RadarRuntime : IDisposable {
 readonly object _gate=new(); readonly SettingsRepository _repository; readonly IWorkerClient _worker; readonly IPlatformServices _platform; readonly Func<DateTimeOffset> _clock;
 readonly ContinuationPolicy _policy=new(); readonly List<ContinuationWork> _queue=[]; readonly List<NoticeRecord> _notices=[]; readonly HashSet<string> _attempted=[]; readonly SharedJournal _journal; readonly CareGate _care;
 List<SessionRecord> _rows=[]; List<string> _errors=[]; double _snapshotAt; double _monitoringAt; bool _disposed; bool _busy; bool _navigating; long _generation; CancellationTokenSource? _operation; ContinuationWork? _active; double _began;
 readonly Dictionary<string,Pending> _confirmations=[]; string _summary="仅提醒，不自动发送";
 sealed record Pending(ContinuationWork Work,double SentAt,double Deadline,string? RunId);
 public RadarSettings Settings{get;private set;}
 public event Action? Changed; public event Action<NoticeRecord>? NoticeRaised;
 public RadarRuntime(SettingsRepository repository,IWorkerClient worker,IPlatformServices platform,Func<DateTimeOffset>? clock=null){_repository=repository;_worker=worker;_platform=platform;_clock=clock??(()=>DateTimeOffset.UtcNow);Settings=repository.Load();_journal=new SharedJournal(repository.DataDirectory);_care=new CareGate(repository.DataDirectory);_worker.Snapshot+=Observe;_worker.Fault+=OnFault;_monitoringAt=Now;}
 double Now=>_clock().ToUnixTimeMilliseconds()/1000d;
 public IReadOnlyList<SessionRecord> Sessions{get{lock(_gate)return _rows.Select(SessionFacts.Clone).ToList();}}
 public IReadOnlyList<SessionRecord> VisibleSessions{get{lock(_gate){var rows=_rows.Where(r=>SessionFacts.IsDisplayable(r)&&!Settings.RemovedIds.Contains(r.Id)).Select(SessionFacts.Clone).ToList();foreach(var r in rows)if(!Fresh){r.Status="unknown";r.StatusReason="会话采集暂未更新，状态待确认";}return rows.Where(r=>r.Status is "running" or "waiting" or "interrupted" or "unknown" || Settings.CareIds.Contains(r.Id)||(r.EndedAt??r.UpdatedAt)>=new DateTimeOffset(_clock().LocalDateTime.Date).ToUnixTimeSeconds()).OrderByDescending(r=>Settings.Pins.Contains(r.Id)).ThenBy(r=>r.UserStopped==true?6:r.Status=="interrupted"?0:r.Status=="running"?1:r.Status=="waiting"?2:4).ThenByDescending(r=>r.UpdatedAt).ToList();}}}
 public IReadOnlyList<NoticeRecord> Notices{get{lock(_gate)return _notices.ToList();}}
 public int QueueCount{get{lock(_gate)return _queue.Count+(_active!=null?1:0);}}
 public bool Fresh=>_snapshotAt>0 && Now-_snapshotAt is >=-2 and <=8;
 public string Summary{get{lock(_gate)return _summary;}}
 public string Diagnostic{get{lock(_gate)return $"运行模式：{(Settings.Mode=="rage"?"狂暴":"协作")}\n自动发送：{(Settings.AutoSend?"开启":"关闭")}\n排队：{QueueCount}\n原会话响应确认最多 30 秒；超时继续只读观察，不重复发送。\n持续关照：{Settings.CareIds.Count} 条；每小时最多自动恢复 3 次。\n采集：{(Fresh?"新鲜":"待确认")}\n{string.Join("\n",_errors)}\n最近结果：{_summary}\n\n最近操作回执（仅元数据）\n{ReceiptLog.Summary(_repository.DataDirectory)}";}}
 public Task StartAsync(CancellationToken token=default){lock(_gate){_monitoringAt=Now;if(Settings.Paused)return Task.CompletedTask;return _worker.StartAsync(token);}}
 void OnFault(string code){lock(_gate){_errors=[Explain(code)];if(code!="collector_restart")_snapshotAt=0;}Changed?.Invoke();}
 void Observe(CollectorSnapshot snapshot){lock(_gate){if(_disposed||Settings.Paused)return;var now=Now;_rows=(snapshot.Sessions??[]).Where(ValidRow).Select(SessionFacts.Clone).ToList();_rows=_rows.Where(r=>r.Source!="window"||!_rows.Any(x=>x.AppId==r.AppId&&x.Source!="window"&&SessionFacts.HasDisplayIdentity(x))).ToList();_errors=(snapshot.Errors??[]).Where(x=>x!=null&&x.Length<512).Take(16).ToList();_snapshotAt=double.IsFinite(snapshot.CollectedAt)?snapshot.CollectedAt:0;if(!Fresh){CancelAll("采集已过期，已取消旧排队");return;}
 var included=_rows.Where(r=>!Settings.RemovedIds.Contains(r.Id)&&Unique(r)).Select(SessionFacts.Clone).ToList();var supervised=Scope(included);
 foreach(var row in included){if(row.AppId=="openclaw"&&row.ContinuousAuthorized==true&&_care.IsCorrelated(Settings,row))row.ManualOnly=false;}
 var events=_policy.Observe(included,now,Settings,supervised);
 foreach(var work in events){var actual=_rows.First(r=>r.Id==work.Session.Id);work.Session=SessionFacts.Clone(actual);work.Care=actual.AppId=="openclaw"&&actual.ContinuousAuthorized==true&&_care.IsCorrelated(Settings,actual);
 if(work.Care&&actual.Status=="completed"){work.CanContinue=false;work.Kind="completion";work.Explanation="这个项目已完结，请验收";}
 if(work.Care&&actual.Status=="interrupted"){work.CanContinue=ContinuationPolicy.Restriction(actual,Settings.RateLimitWake)==null&&_care.BudgetOpen(actual.Id,now)&&(actual.CareRetryAt??0)<=now;work.Explanation=work.CanContinue?"持续关照已发现明确中断，准备恢复原会话":"持续关照已达到恢复保护，仍在观察，请检查连续失败原因";}
 if(work.CanContinue&&Settings.AutoSend)Enqueue(work);else Notice(work,work.CanContinue&&!Settings.AutoSend?"自动发送未开启，仅提醒。"+work.Explanation:work.Explanation);}
 Confirm(now); }Changed?.Invoke();Tick();}
 static bool ValidRow(SessionRecord r)=>r!=null&&!string.IsNullOrWhiteSpace(r.Id)&&r.Id.Length<=512&&!string.IsNullOrWhiteSpace(r.Title)&&r.Title.Length<=512&&!string.IsNullOrEmpty(r.AppId)&&r.Project!=null&&r.Source!=null&&r.Target!=null&&double.IsFinite(r.UpdatedAt)&&(r.StartedAt is not double start||double.IsFinite(start))&&(r.EndedAt is not double end||double.IsFinite(end));
 bool Unique(SessionRecord row)=>_rows.Count(r=>r.Id==row.Id)==1;
 HashSet<string> Scope(IEnumerable<SessionRecord> rows)=>rows.Where(r=>Settings.SupervisedIds.Contains(r.Id)||Settings.SupervisedApps.Contains(r.AppId)||Settings.CareIds.Contains(r.Id)).Select(r=>r.Id).ToHashSet();
 void Enqueue(ContinuationWork work){if(_attempted.Contains(work.Key)||_active?.Key==work.Key||_queue.Any(w=>w.Key==work.Key)||_confirmations.ContainsKey(work.Key))return;work.NotBefore=Now+Math.Clamp(double.IsFinite(work.Delay)?work.Delay:10,0,10);_queue.Add(work);Record(work,"queued","queued");Notice(work,work.Manual?"已排定单次恢复":"已排定恢复；按顺序核验原会话");}
 public void Tick(){lock(_gate){if(_disposed||Settings.Paused)return;var now=Now;if(!Fresh){CancelAll("采集已过期，停止自动操作");return;}Confirm(now);if(_busy||_navigating||_active!=null)return;if(_queue.Count==0)return;var work=_queue[0];if(work.NotBefore>now||(!Settings.AutoSend&&!work.Manual))return;var current=_rows.FirstOrDefault(r=>r.Id==work.Session.Id);if(current==null||!Unique(current)||Settings.RemovedIds.Contains(current.Id)||!SameIdentity(current,work.Session)||SessionFacts.RoundKey(current)!=work.Key||current.Status!=(work.Kind=="followup"?"completed":"interrupted")){_queue.RemoveAt(0);Notice(work,"会话身份、状态或轮次已变化，已取消恢复");return;}var restriction=work.Kind=="followup"?ContinuationPolicy.FollowupRestriction(current):ContinuationPolicy.Restriction(current,work.BypassRestriction,work.Manual);if(restriction!=null){_queue.RemoveAt(0);Notice(work,restriction);return;}if(current.ManualOnly==true&&!work.Manual&&!(current.ContinuousAuthorized==true&&_care.IsCorrelated(Settings,current))){_queue.RemoveAt(0);Notice(work,"后台任务尚未授权持续关照，只提醒");return;}if(current.AppId!="openclaw"&&(!_platform.DesktopUsable||!double.IsFinite(_platform.IdleSeconds)||_platform.IdleSeconds<2)){Notice(work,"等待桌面可用和键鼠静止两秒");return;}
 if(work.Kind=="followup" && !work.Manual){var n=Settings.SendCounts.GetValueOrDefault(current.Id)+1;work.Text=n%Settings.AlternateEvery==0?Settings.AlternateText:ContinuationPolicy.Continue(current.AppId,Settings);}
 if(StagePolicy.ValidateSendText(work.Text)!=null||string.IsNullOrWhiteSpace(work.Text)){_queue.RemoveAt(0);Notice(work,"提示词为空或超过 2000 字符，已停止");return;}
 var request=Request(current,work);var verdict=_journal.Check(request,now);if(verdict.Code!=null){_queue.RemoveAt(0);Notice(work,Explain(verdict.Code));return;}_queue.RemoveAt(0);_active=work;_busy=true;_began=now;_operation=new CancellationTokenSource();var generation=_generation;var token=_operation.Token;Notice(work,current.AppId=="openclaw"?"正在后台核验并恢复原会话":"正在定位原会话并检查输入框");_ = Send(work,request,generation,token);}}
 async Task Send(ContinuationWork work,Dictionary<string,object?> request,long generation,CancellationToken token){BridgeResult result;try{result=await _worker.RunBridgeAsync(request,token);}catch{result=new BridgeResult{Code="bridge_error",Attempted=true};}lock(_gate){if(_disposed||generation!=_generation){if(result.Attempted)_attempted.Add(work.Key);return;}_busy=false;_active=null;_operation?.Dispose();_operation=null;
 if(result.Attempted){_attempted.Add(work.Key);_policy.RecordAttempt(work.Session.Id,Now);var persisted=_journal.Check(request,Now);if(persisted.Code!="already_attempted")_journal.Reserve(request,Now);if(work.Care&&!work.Manual){try{_care.Record(work.Session.Id,Now);}catch{_summary="持续关照记录暂不可保存，后续自动恢复将保持停止";}}}
 Record(work,"send",result.Code,result.Attempted);
 if(result.Code is "sent" or "sent_pending_confirmation"){var sent=result.SentAt??Now;_confirmations[work.Key]=new Pending(work,sent,Now+30,result.RunId);_active=work;if(work.AutomationMode=="rage"&&!work.Manual){Settings.SendCounts[work.Session.Id]=Settings.SendCounts.GetValueOrDefault(work.Session.Id)+1;_repository.Save(Settings);}Notice(work,"已发送，等待原会话新轮次",30);}
 else if(!result.Attempted&&work.RouteRetries<3&&new[]{"user_active","locked","permission_required","focus_changed","another_recovery","cooldown","state_unverified","openclaw_gateway_unavailable","send_unavailable","composer_unreadable","search_unavailable"}.Contains(result.Code)){work.RouteRetries++;work.NotBefore=Now+Math.Clamp(result.RetryAfter??2,1,10);_queue.Insert(0,work);Notice(work,"准备暂未完成，保留原位重新核验");}
 else Notice(work,Explain(result.Code));}Changed?.Invoke();Tick();}
 void Confirm(double now){foreach(var pair in _confirmations.ToList()){if(now-pair.Value.SentAt>600){_confirmations.Remove(pair.Key);continue;}var pending=pair.Value;var work=pending.Work;var row=_rows.FirstOrDefault(r=>r.Id==work.Session.Id);if(row!=null&&Unique(row)&&SameIdentity(row,work.Session)&&row.UserStopped!=true&&row.Status is "running" or "completed" or "interrupted"&&row.StartedAt>work.Session.StartedAt&&row.StartedAt>= (row.AppId is "codex" or "openclaw"?pending.SentAt:Math.Floor(pending.SentAt))&&(row.AppId!="openclaw"||pending.RunId!=null&&row.RunId==pending.RunId)){_confirmations.Remove(pair.Key);if(_active?.Key==pair.Key)_active=null;Record(work,"new-round","confirmed",true);Notice(work,"已确认原会话开始新轮次");_policy.ObserveConfirmedRound(row,now);}
 else if(now>=pending.Deadline&&_active?.Key==pair.Key){_active=null;Record(work,"timeout","response_timeout",true);Notice(work,"30 秒内未确认新轮次；继续观察，不重复发送");_confirmations[pair.Key]=pending with{Deadline=double.PositiveInfinity};}
 else if(_active?.Key==pair.Key)Notice(work,"等待原会话新轮次",(int)Math.Ceiling(pending.Deadline-now));}}
 Dictionary<string,object?> Request(SessionRecord row,ContinuationWork w)=>new(){["mode"]="send",["pid"]=row.Pid,["id"]=row.Id,["app_id"]=row.AppId,["title"]=row.Title,["project"]=row.Project,["source"]=row.Source,["target"]=row.Target,["key"]=w.Key,["started_at"]=row.StartedAt,["navigation_key"]=row.NavigationKey,["navigation_title"]=row.NavigationTitle,["lifecycle_revision"]=row.LifecycleRevision,["continuous_authorized"]=w.Care,["operation_id"]=w.OperationId,["text"]=w.Text,["overwrite_draft"]=true,["kind"]=w.Kind,["manual_retry"]=w.Manual,["allow_rate_limit"]=w.BypassRestriction,["automation_mode"]=w.AutomationMode};
 static bool SameIdentity(SessionRecord a,SessionRecord b)=>a.Id==b.Id&&a.AppId==b.AppId&&a.Title==b.Title&&a.Project==b.Project&&a.Source==b.Source&&a.NavigationKey==b.NavigationKey&&a.Target==b.Target;
 void Notice(ContinuationWork work,string text,int? seconds=null){_summary=text;var n=new NoticeRecord(work.OperationId,work.Session.Id,work.Session.AppName+(work.Kind=="completion"?" · 完成待验收":" · 中断恢复"),work.Session.Title,text,work.Kind,!_attempted.Contains(work.Key)&&!_queue.Any(x=>x.Key==work.Key)&&_active?.Key!=work.Key&&work.Session.UserStopped!=true,_active?.Key==work.Key||_queue.Any(x=>x.Key==work.Key),seconds);var index=_notices.FindIndex(x=>x.SessionId==n.SessionId);if(index<0)_notices.Add(n);else _notices[index]=n;NoticeRaised?.Invoke(n);}
 void Record(ContinuationWork work,string stage,string code,bool attempted=false){try{ReceiptLog.Append(_repository.DataDirectory,work.OperationId,work.Session.Id,work.Key,work.Session.AppId,stage,code,attempted,Now,work.DetectedAt);}catch{}}
 void CancelAll(string reason){_generation++;_operation?.Cancel();_operation?.Dispose();_operation=null;_busy=false;var cancelled=_queue.Concat(_active==null?[]:new[]{_active}).ToList();_queue.Clear();_active=null;_confirmations.Clear();_policy.ResetObservation();foreach(var w in cancelled){Record(w,"cancel","cancelled");Notice(w,reason);}}
 string RuleSignature(RadarSettings s)=>JsonSerializer.Serialize(new{s.AutoSend,s.Paused,s.Mode,s.ResumeText,s.InterruptText,s.ContinueText,s.AlternateText,s.AlternateEvery,s.RateLimitWake,s.RateLimitSeconds,s.RateLimitText,s.AppContinueTexts,s.AppResumeTexts,s.SupervisedIds,s.SupervisedApps,s.CareIds,s.RemovedIds,s.OpenClawGateway,s.OpenClawHome,s.WslDistribution,s.WslExecutable});
 public void UpdateSettings(Action<RadarSettings> change){lock(_gate){var before=RuleSignature(Settings);var wasPaused=Settings.Paused;var next=SettingsRepository.Clone(Settings);change(next);if(RuleSignature(next)!=before)CancelAll("设置或监督范围已变化，已取消旧排队");_repository.WriteCareRegistry(next);WritePlatformConfig(next);_repository.Save(next);Settings=next;if(wasPaused!=Settings.Paused){if(Settings.Paused)_worker.Stop();else {_snapshotAt=0;_monitoringAt=Now;_ = _worker.StartAsync();}}}Changed?.Invoke();}
 void WritePlatformConfig(RadarSettings settings){AtomicFile.Write(_repository.DataDirectory,"openclaw-local-gateway.json",JsonSerializer.SerializeToUtf8Bytes(new{url=settings.OpenClawGateway}));AtomicFile.Write(_repository.DataDirectory,"platform-config.json",JsonSerializer.SerializeToUtf8Bytes(new{openclaw_home=settings.OpenClawHome,wsl_distribution=settings.WslDistribution,wsl_executable=settings.WslExecutable}));}
 public void ToggleSupervision(SessionRecord row){if(Settings.CareIds.Contains(row.Id)){ToggleCare(row);return;}UpdateSettings(s=>{if(!s.SupervisedIds.Remove(row.Id))s.SupervisedIds.Add(row.Id);});}
 public void ToggleAppSupervision(string app)=>UpdateSettings(s=>{if(!s.SupervisedApps.Remove(app))s.SupervisedApps.Add(app);});
 public void ToggleCare(SessionRecord row){if(row.AppId!="openclaw"||!StagePolicy.OpenClawId.IsMatch(row.Id)||row.Source!="local-db")return;UpdateSettings(s=>{if(!s.CareIds.Remove(row.Id))s.CareIds.Add(row.Id);});}
 public void Remove(SessionRecord row)=>UpdateSettings(s=>s.RemovedIds.Add(row.Id));public void RestoreRemoved()=>UpdateSettings(s=>s.RemovedIds.Clear());
 public void ManualResume(SessionRecord row){lock(_gate){if(Settings.Paused||!Fresh||!Unique(row))return;var current=_rows.First(r=>r.Id==row.Id);var kind=current.Status=="completed"?"followup":"interrupt";var restriction=current.Status=="completed"?ContinuationPolicy.FollowupRestriction(current):ContinuationPolicy.Restriction(current,Settings.RateLimitWake,true);if(current.Status is not ("completed" or "interrupted")||restriction!=null){_summary=restriction??"会话状态尚不能恢复";return;}var key=SessionFacts.RoundKey(current);var queued=_queue.FirstOrDefault(w=>w.Key==key);if(queued!=null){queued.Manual=true;return;}Enqueue(new ContinuationWork{Session=SessionFacts.Clone(current),Key=key,DetectedAt=Now,CanContinue=true,Kind=kind,Manual=true,Text=kind=="followup"?ContinuationPolicy.ManualContinueText:ContinuationPolicy.Resume(current.AppId,Settings),Delay=3,AutomationMode=Settings.Mode,Care=Settings.CareIds.Contains(current.Id)});}Changed?.Invoke();Tick();}
 public void StartCompletedSelected(){lock(_gate){if(Settings.Mode!="rage"||!Settings.AutoSend||Settings.Paused||!Fresh)return;foreach(var w in _policy.StartCompleted(_rows.Where(r=>!Settings.RemovedIds.Contains(r.Id)&&!Settings.CareIds.Contains(r.Id)).ToList(),Now,Scope(_rows)))Enqueue(w);}Changed?.Invoke();}
 public void AcknowledgeNotice(string id){lock(_gate)_notices.RemoveAll(n=>n.Id==id);Changed?.Invoke();}
 public async Task<BridgeResult> InspectAsync(SessionRecord row,CancellationToken token=default){var request=new Dictionary<string,object?>{["mode"]="inspect",["id"]=row.Id,["app_id"]=row.AppId,["title"]=row.Title,["project"]=row.Project,["source"]=row.Source,["target"]=row.Target,["key"]=SessionFacts.RoundKey(row),["started_at"]=row.StartedAt,["navigation_key"]=row.NavigationKey,["navigation_title"]=row.NavigationTitle,["manual_retry"]=row.ManualOnly==true};return await _worker.RunBridgeAsync(request,token);}
 public async Task<NavigationResult> OpenAsync(SessionRecord row,CancellationToken token=default){lock(_gate){if(_busy||_active!=null||_navigating)return new(false,"正在处理前一条会话，请稍候");_navigating=true;}try{return await _platform.OpenAsync(row,token);}finally{lock(_gate)_navigating=false;}}
 public void Dispose(){lock(_gate){if(_disposed)return;_disposed=true;CancelAll("监控已停止");_worker.Snapshot-=Observe;_worker.Fault-=OnFault;_worker.Stop();_worker.Dispose();try{_platform.SetKeepAwake(false);}catch{}}}
 public static string Explain(string code)=>code switch{"ready"=>"组件已就绪","already_running"=>"原会话仍在运行，无需恢复","already_attempted"=>"本轮已经尝试，保持防重复保护","user_stopped"=>"你已主动停止，本轮保持停止","target_unverified"=>"无法核验原会话，未写入或发送","input_changed"=>"输入回读不一致，已停止；请检查原会话","send_unavailable"=>"未找到唯一可用发送按钮，未发送","state_unverified"=>"本轮状态待确认，仅提醒","permission_required"=>"目标窗口暂不可读，请检查进程权限与窗口状态","openclaw_gateway_unavailable"=>"本地 OpenClaw 网关暂不可用，未发送","openclaw_cli_unavailable"=>"未找到本地 OpenClaw 命令行入口","openclaw_care_cooldown"=>"持续关照已达到每小时三次恢复，继续观察","openclaw_care_state_unavailable"=>"持续关照记录暂不可读，只提醒","openclaw_endpoint_invalid"=>"OpenClaw 本地网关地址无效","preview_sending_disabled"=>"独立验收已禁用发送","collector_unavailable"=>"本地采集组件暂不可用","bridge_timeout"=>"恢复请求未确认；本轮不重复发送",_=>"本轮未完成恢复，请使用只读检查查看原会话状态"};
}
